#!/usr/bin/env python3
"""Generate literal native x86 register lane/bitwise cases from compact inputs."""
from pathlib import Path
import argparse
import json
ROOT=Path(__file__).resolve().parents[1]
def generate():
 s=json.loads((ROOT/'tests/sdk/linux-host/sparse-vector-lanes-cases.json').read_text())
 lines=['''// SPDX-License-Identifier: GPL-3.0-or-later
// Generated by scripts/generate-sparse-vector-lanes-tests.py; x86 supplies results.
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#define EXEC(bytes) __asm__ volatile("movdqu %[old], %%xmm0; movdqu %[src], %%xmm1; pushfq; pop %[original]; push %[seed]; popfq; " bytes "; pushfq; pop %[flags]; push %[original]; popfq; movdqu %%xmm0, %[dst]; movdqu %%xmm1, %[kept]" : [original] "=&r"(original), [flags] "=&r"(flags), "+a"(value), [dst] "=m"(dst), [kept] "=m"(kept) : [seed] "r"(seed), [old] "m"(old), [src] "m"(src) : "xmm0","xmm1","cc","memory")
int main(void){
 const uint64_t patterns[][4]={'''+','.join('{'+','.join('UINT64_C('+n+')' for n in p)+'}' for p in s['patterns'])+'''};
 const unsigned seeds[]={'''+','.join(str(n) for n in s['flagSeeds'])+'''};uint64_t current;__asm__ volatile("pushfq; pop %0":"=r"(current)::"memory");int comma=0;puts("[");
 for(unsigned form=0;form<@FORMS@;form++)for(unsigned self=0;self<2;self++)for(unsigned p=0;p<@PATTERNS@;p++)for(unsigned si=0;si<@SEEDS@;si++){
  const uint64_t old[]={patterns[p][0],patterns[p][1]},src[]={patterns[p][2],patterns[p][3]},seed=(current&~UINT64_C(0xcd5))|seeds[si];uint64_t value=UINT64_C(0xdeadbeef01234567),dst[2],kept[2],original,flags;
  switch(form*2+self){''']
 for i,f in enumerate(s['forms']):
  for self in [0,1]:
   code=([f['prefix']]if f['prefix']else[])+[15,f['opcode'],0xc0 if self else 0xc1]
   lines.append('case '+str(i*2+self)+':EXEC(".byte '+','.join(hex(b)for b in code)+'");break;')
 lines.append('''default:return 2;}
  printf("%s[%u,%u,%u,%u,\\"0x%" PRIx64 "\\",\\"0x%" PRIx64 "\\",\\"0x%" PRIx64 "\\",\\"0x%" PRIx64 "\\",\\"0x%" PRIx64 "\\",%u]",comma?",\\n":"",form,self,p,si,value,dst[0],dst[1],kept[0],kept[1],(unsigned)flags&0xcd5);comma=1;
 }puts("\\n]");return 0;
}
''')
 return '\n'.join(lines).replace('@FORMS@',str(len(s['forms']))).replace('@PATTERNS@',str(len(s['patterns']))).replace('@SEEDS@',str(len(s['flagSeeds'])))
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--check',action='store_true');args=p.parse_args();dest=ROOT/'tests/sdk/linux-host/sparse-vector-lanes-oracle.c';text=generate()
 if args.check:
  if dest.read_text()!=text:raise SystemExit('Generated lane oracle source differs')
  print('Literal lane oracle source matches compact cases')
 else:dest.write_text(text)
if __name__=='__main__':main()
